import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function StudentProfile() {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [stats, setStats] = useState(null);
  const [securityInfo, setSecurityInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [statsLoading, setStatsLoading] = useState(true);
  const [securityLoading, setSecurityLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [showChangePassword, setShowChangePassword] = useState(false);
  const [formData, setFormData] = useState({
    nom: '',
    email: ''
  });
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [passwordError, setPasswordError] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login');
      return;
    }
    fetchProfile();
    fetchStats();
    fetchSecurityInfo();
  }, [navigate]);

  const fetchProfile = async () => {
    try {
      setLoading(true);
      setError('');
      console.log('🔄 Chargement du profil étudiant...');
      
      const response = await api.get('/api/student/profile');
      console.log('✅ Réponse API profil:', response.data);
      
      if (response.data.success) {
        setProfile(response.data.profile);
        setFormData({
          nom: response.data.profile.nom,
          email: response.data.profile.email
        });
      } else {
        throw new Error(response.data.message || 'Erreur inconnue');
      }
    } catch (error) {
      console.error('❌ Erreur chargement profil:', error);
      const errorMsg = error.response?.data?.message || error.message || 'Erreur lors du chargement du profil';
      setError(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      setStatsLoading(true);
      console.log('📊 Chargement des statistiques...');
      
      const response = await api.get('/api/student/stats');
      console.log('✅ Réponse API stats:', response.data);
      
      if (response.data.success) {
        setStats(response.data.stats);
      } else {
        console.warn('⚠️ Statistiques non disponibles:', response.data.message);
        // Utiliser des valeurs par défaut si les stats ne sont pas disponibles
        setStats({
          total_cours: 0,
          total_devoirs: 0,
          total_notes: 0,
          moyenne_generale: 0,
          assiduite: 0
        });
      }
    } catch (error) {
      console.error('❌ Erreur chargement statistiques:', error);
      // Valeurs par défaut en cas d'erreur
      setStats({
        total_cours: 0,
        total_devoirs: 0,
        total_notes: 0,
        moyenne_generale: 0,
        assiduite: 0
      });
    } finally {
      setStatsLoading(false);
    }
  };

  const fetchSecurityInfo = async () => {
    try {
      setSecurityLoading(true);
      const response = await api.get('/api/student/security-info');
      if (response.data.success) {
        setSecurityInfo(response.data.securityInfo);
      }
    } catch (error) {
      console.error('❌ Erreur chargement infos sécurité:', error);
      // Utiliser des valeurs par défaut
      setSecurityInfo({
        derniere_connexion: new Date().toISOString(),
        date_creation_compte: new Date().toISOString(),
        nb_changements_mdp: 0
      });
    } finally {
      setSecurityLoading(false);
    }
  };

  // FONCTION MANQUANTE - AJOUTÉE ICI
  const handleBack = () => {
    navigate('/dashboard-student');
  };

  const handleEdit = () => {
    setEditing(true);
  };

  const handleCancel = () => {
    setEditing(false);
    setFormData({
      nom: profile.nom,
      email: profile.email
    });
    setMessage('');
    setError('');
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setError('');
      const response = await api.put('/api/student/security-info', formData);
      
      if (response.data.success) {
        setProfile(response.data.profile);
        setEditing(false);
        setMessage('Profil mis à jour avec succès!');
        
        // Mettre à jour les données dans le localStorage
        const userData = JSON.parse(localStorage.getItem('user'));
        const updatedUser = { ...userData, nom: formData.nom, email: formData.email };
        localStorage.setItem('user', JSON.stringify(updatedUser));
      } else {
        throw new Error(response.data.message || 'Erreur inconnue');
      }
    } catch (error) {
      console.error('❌ Erreur mise à jour profil:', error);
      setError(error.response?.data?.message || 'Erreur lors de la mise à jour du profil');
    }
  };

  const handleChangePassword = () => {
    setShowChangePassword(true);
    setPasswordError('');
    setPasswordData({
      currentPassword: '',
      newPassword: '',
      confirmPassword: ''
    });
  };

  const handlePasswordChange = (e) => {
    const { name, value } = e.target;
    setPasswordData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handlePasswordSubmit = async (e) => {
    e.preventDefault();
    try {
      setPasswordError('');

      // Validation côté client
      if (passwordData.newPassword.length < 6) {
        setPasswordError('Le mot de passe doit contenir au moins 6 caractères');
        return;
      }

      if (passwordData.newPassword !== passwordData.confirmPassword) {
        setPasswordError('Les mots de passe ne correspondent pas');
        return;
      }

      const response = await api.put('/student/change-password', passwordData);
      
      if (response.data.success) {
        setMessage('Mot de passe mis à jour avec succès!');
        setShowChangePassword(false);
        setPasswordData({
          currentPassword: '',
          newPassword: '',
          confirmPassword: ''
        });
        
        // Rafraîchir les informations de sécurité
        fetchSecurityInfo();
      } else {
        setPasswordError(response.data.message || 'Erreur inconnue');
      }
    } catch (error) {
      console.error('❌ Erreur changement mot de passe:', error);
      setPasswordError(error.response?.data?.message || 'Erreur lors du changement de mot de passe');
    }
  };

  const cancelPasswordChange = () => {
    setShowChangePassword(false);
    setPasswordError('');
    setPasswordData({
      currentPassword: '',
      newPassword: '',
      confirmPassword: ''
    });
  };

  // Fonction pour évaluer la force du mot de passe
  const getPasswordStrength = (password) => {
    if (!password) return { strength: '', text: '' };
    
    let strength = 0;
    if (password.length >= 6) strength++;
    if (password.length >= 8) strength++;
    if (/[A-Z]/.test(password)) strength++;
    if (/[0-9]/.test(password)) strength++;
    if (/[^A-Za-z0-9]/.test(password)) strength++;

    const strengths = {
      0: { strength: 'weak', text: 'Très faible' },
      1: { strength: 'weak', text: 'Faible' },
      2: { strength: 'medium', text: 'Moyen' },
      3: { strength: 'medium', text: 'Bon' },
      4: { strength: 'strong', text: 'Fort' },
      5: { strength: 'strong', text: 'Très fort' }
    };

    return strengths[strength] || strengths[0];
  };

  const passwordStrength = getPasswordStrength(passwordData.newPassword);

  // Styles
  const styles = {
    container: {
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      fontFamily: 'Arial, sans-serif'
    },
    header: {
      background: 'rgba(255, 255, 255, 0.95)',
      padding: '1rem 2rem',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      borderBottom: '1px solid rgba(255, 255, 255, 0.2)'
    },
    backButton: {
      background: 'none',
      border: '2px solid #667eea',
      color: '#667eea',
      padding: '0.5rem 1rem',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    title: {
      color: '#2d3748',
      margin: 0
    },
    headerActions: {
      display: 'flex',
      alignItems: 'center',
      gap: '1rem'
    },
    roleBadge: {
      background: 'linear-gradient(135deg, #667eea, #764ba2)',
      color: 'white',
      padding: '0.5rem 1rem',
      borderRadius: '20px',
      fontSize: '0.8rem',
      fontWeight: 'bold'
    },
    main: {
      maxWidth: '1200px',
      margin: '0 auto',
      padding: '2rem'
    },
    successAlert: {
      background: '#d4edda',
      color: '#155724',
      padding: '1rem',
      borderRadius: '8px',
      marginBottom: '1rem',
      border: '1px solid #c3e6cb'
    },
    errorAlert: {
      background: '#f8d7da',
      color: '#721c24',
      padding: '1rem',
      borderRadius: '8px',
      marginBottom: '1rem',
      border: '1px solid #f5c6cb'
    },
    profileGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))',
      gap: '2rem'
    },
    infoCard: {
      background: 'rgba(255, 255, 255, 0.95)',
      padding: '2rem',
      borderRadius: '15px',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)',
      gridColumn: '1 / -1'
    },
    statsCard: {
      background: 'rgba(255, 255, 255, 0.95)',
      padding: '2rem',
      borderRadius: '15px',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
    },
    securityCard: {
      background: 'rgba(255, 255, 255, 0.95)',
      padding: '2rem',
      borderRadius: '15px',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
    },
    cardHeader: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '2rem'
    },
    cardTitle: {
      color: '#2d3748',
      margin: 0
    },
    editButton: {
      background: 'linear-gradient(135deg, #667eea, #764ba2)',
      color: 'white',
      border: 'none',
      padding: '0.75rem 1.5rem',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    form: {
      display: 'flex',
      flexDirection: 'column',
      gap: '1.5rem'
    },
    formGroup: {
      display: 'flex',
      flexDirection: 'column',
      gap: '0.5rem'
    },
    label: {
      fontWeight: '600',
      color: '#4a5568'
    },
    input: {
      padding: '0.75rem',
      border: '2px solid #e2e8f0',
      borderRadius: '8px',
      fontSize: '1rem',
      transition: 'border-color 0.3s ease'
    },
    formActions: {
      display: 'flex',
      gap: '1rem',
      marginTop: '1rem'
    },
    saveButton: {
      background: '#48bb78',
      color: 'white',
      border: 'none',
      padding: '0.75rem 1.5rem',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    cancelButton: {
      background: '#e53e3e',
      color: 'white',
      border: 'none',
      padding: '0.75rem 1.5rem',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    profileInfo: {
      display: 'flex',
      flexDirection: 'column',
      gap: '1rem'
    },
    infoItem: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '0.75rem 0',
      borderBottom: '1px solid #e2e8f0'
    },
    roleText: {
      background: '#667eea',
      color: 'white',
      padding: '0.25rem 0.75rem',
      borderRadius: '15px',
      fontSize: '0.8rem',
      fontWeight: '600'
    },
    statsGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))',
      gap: '1rem'
    },
    statItem: {
      textAlign: 'center',
      padding: '1rem',
      background: 'rgba(102, 126, 234, 0.1)',
      borderRadius: '10px'
    },
    statNumber: {
      fontSize: '1.5rem',
      fontWeight: 'bold',
      color: '#667eea',
      marginBottom: '0.5rem'
    },
    statLabel: {
      fontSize: '0.8rem',
      color: '#718096'
    },
    securityInfo: {
      display: 'flex',
      flexDirection: 'column',
      gap: '1rem'
    },
    securityItem: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '1rem',
      background: 'rgba(102, 126, 234, 0.05)',
      borderRadius: '8px'
    },
    securityLabel: {
      fontWeight: '600',
      color: '#4a5568'
    },
    securityStatus: {
      color: '#718096'
    },
    securityButton: {
      background: 'none',
      border: '2px solid #667eea',
      color: '#667eea',
      padding: '0.5rem 1rem',
      borderRadius: '6px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    loadingContainer: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white'
    },
    spinner: {
      width: '50px',
      height: '50px',
      border: '4px solid rgba(255, 255, 255, 0.3)',
      borderLeft: '4px solid white',
      borderRadius: '50%',
      animation: 'spin 1s linear infinite',
      marginBottom: '1rem'
    },
    statLoading: {
      fontSize: '0.9rem',
      color: '#718096',
      fontStyle: 'italic'
    },
    securityLoading: {
      fontSize: '0.9rem',
      color: '#718096',
      fontStyle: 'italic'
    },
    // Styles pour le formulaire de mot de passe
    passwordOverlay: {
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundColor: 'rgba(0, 0, 0, 0.5)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 1000
    },
    passwordModal: {
      background: 'white',
      padding: '2rem',
      borderRadius: '15px',
      boxShadow: '0 10px 40px rgba(0, 0, 0, 0.3)',
      width: '90%',
      maxWidth: '500px'
    },
    passwordForm: {
      display: 'flex',
      flexDirection: 'column',
      gap: '1.5rem'
    },
    passwordFormGroup: {
      display: 'flex',
      flexDirection: 'column',
      gap: '0.5rem'
    },
    passwordLabel: {
      fontWeight: '600',
      color: '#2d3748',
      fontSize: '0.9rem'
    },
    passwordInput: {
      padding: '0.75rem',
      border: '2px solid #e2e8f0',
      borderRadius: '8px',
      fontSize: '1rem',
      transition: 'border-color 0.3s ease'
    },
    passwordInputError: {
      borderColor: '#e53e3e'
    },
    passwordError: {
      color: '#e53e3e',
      fontSize: '0.8rem',
      marginTop: '0.25rem'
    },
    passwordActions: {
      display: 'flex',
      gap: '1rem',
      justifyContent: 'flex-end',
      marginTop: '1rem'
    },
    passwordStrength: {
      fontSize: '0.8rem',
      marginTop: '0.25rem'
    },
    passwordWeak: {
      color: '#e53e3e'
    },
    passwordMedium: {
      color: '#d69e2e'
    },
    passwordStrong: {
      color: '#38a169'
    }
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.spinner}></div>
        <p>Chargement de votre profil...</p>
      </div>
    );
  }

  if (!profile) {
    return (
      <div style={styles.container}>
        <div style={styles.errorAlert}>
          {error || 'Impossible de charger votre profil'}
          <button onClick={fetchProfile} style={{ marginLeft: '1rem', padding: '0.5rem 1rem' }}>
            🔄 Réessayer
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <button onClick={handleBack} style={styles.backButton}>
          ← Retour au Dashboard
        </button>
        <h1 style={styles.title}>Mon Profil</h1>
        <div style={styles.headerActions}>
          <span style={styles.roleBadge}>ÉTUDIANT</span>
        </div>
      </header>

      <main style={styles.main}>
        {message && (
          <div style={styles.successAlert}>
            {message}
          </div>
        )}

        {error && (
          <div style={styles.errorAlert}>
            {error}
          </div>
        )}

        <div style={styles.profileGrid}>
          {/* Carte d'information */}
          <div style={styles.infoCard}>
            <div style={styles.cardHeader}>
              <h2 style={styles.cardTitle}>Informations Personnelles</h2>
              {!editing && (
                <button onClick={handleEdit} style={styles.editButton}>
                  ✏️ Modifier
                </button>
              )}
            </div>

            {editing ? (
              <form onSubmit={handleSubmit} style={styles.form}>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Nom complet</label>
                  <input
                    type="text"
                    name="nom"
                    value={formData.nom}
                    onChange={handleChange}
                    style={styles.input}
                    required
                  />
                </div>

                <div style={styles.formGroup}>
                  <label style={styles.label}>Email</label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    style={styles.input}
                    required
                  />
                </div>

                <div style={styles.formActions}>
                  <button type="submit" style={styles.saveButton}>
                    💾 Enregistrer
                  </button>
                  <button type="button" onClick={handleCancel} style={styles.cancelButton}>
                    ❌ Annuler
                  </button>
                </div>
              </form>
            ) : (
              <div style={styles.profileInfo}>
                <div style={styles.infoItem}>
                  <strong>Nom complet:</strong> {profile.nom}
                </div>
                <div style={styles.infoItem}>
                  <strong>Email:</strong> {profile.email}
                </div>
                <div style={styles.infoItem}>
                  <strong>Rôle:</strong> 
                  <span style={styles.roleText}>Étudiant</span>
                </div>
                <div style={styles.infoItem}>
                  <strong>Classe:</strong> {profile.class_name || 'Non assignée'}
                </div>
                <div style={styles.infoItem}>
                  <strong>Niveau:</strong> {profile.class_niveau || 'Non spécifié'}
                </div>
                <div style={styles.infoItem}>
                  <strong>Promotion:</strong> {profile.promotion || '2023-2024'}
                </div>
                <div style={styles.infoItem}>
                  <strong>ID Étudiant:</strong> {profile.id}
                </div>
              </div>
            )}
          </div>

          {/* Carte de statistiques */}
          <div style={styles.statsCard}>
            <h2 style={styles.cardTitle}>
              Statistiques 
              <button 
                onClick={fetchStats} 
                style={{ 
                  background: 'none', 
                  border: 'none', 
                  fontSize: '0.8rem', 
                  marginLeft: '1rem',
                  cursor: 'pointer'
                }}
                title="Actualiser les statistiques"
              >
                🔄
              </button>
            </h2>
            
            {statsLoading ? (
              <div style={styles.statLoading}>
                Chargement des statistiques...
              </div>
            ) : stats ? (
              <div style={styles.statsGrid}>
                <div style={styles.statItem}>
                  <div style={styles.statNumber}>{stats.total_cours}</div>
                  <div style={styles.statLabel}>Cours suivis</div>
                </div>
                <div style={styles.statItem}>
                  <div style={styles.statNumber}>{stats.total_devoirs}</div>
                  <div style={styles.statLabel}>Devoirs</div>
                </div>
                <div style={styles.statItem}>
                  <div style={styles.statNumber}>{stats.moyenne_generale}</div>
                  <div style={styles.statLabel}>Moyenne</div>
                </div>
                <div style={styles.statItem}>
                  <div style={styles.statNumber}>{stats.assiduite}%</div>
                  <div style={styles.statLabel}>Assiduité</div>
                </div>
              </div>
            ) : (
              <div style={styles.statLoading}>
                Statistiques non disponibles
              </div>
            )}
            
            {/* Informations supplémentaires */}
            {stats && stats.total_notes > 0 && (
              <div style={{ 
                marginTop: '1rem', 
                padding: '0.5rem', 
                background: 'rgba(102, 126, 234, 0.05)', 
                borderRadius: '8px',
                fontSize: '0.8rem',
                color: '#718096'
              }}>
                📝 <strong>{stats.total_notes}</strong> notes enregistrées
              </div>
            )}
          </div>

          {/* Carte de sécurité */}
          <div style={styles.securityCard}>
            <h2 style={styles.cardTitle}>Sécurité</h2>
            
            {securityLoading ? (
              <div style={styles.securityLoading}>
                Chargement des informations de sécurité...
              </div>
            ) : (
              <div style={styles.securityInfo}>
                <div style={styles.securityItem}>
                  <span style={styles.securityLabel}>Mot de passe</span>
                  <span style={styles.securityStatus}>••••••••</span>
                  <button onClick={handleChangePassword} style={styles.securityButton}>
                    Changer
                  </button>
                </div>
                <div style={styles.securityItem}>
                  <span style={styles.securityLabel}>Dernière connexion</span>
                  <span style={styles.securityStatus}>
                    {securityInfo?.derniere_connexion 
                      ? new Date(securityInfo.derniere_connexion).toLocaleDateString('fr-FR')
                      : 'Aujourd\'hui'
                    }
                  </span>
                </div>
                <div style={styles.securityItem}>
                  <span style={styles.securityLabel}>Compte créé le</span>
                  <span style={styles.securityStatus}>
                    {securityInfo?.date_creation_compte 
                      ? new Date(securityInfo.date_creation_compte).toLocaleDateString('fr-FR')
                      : 'Date inconnue'
                    }
                  </span>
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Modal de changement de mot de passe */}
      {showChangePassword && (
        <div style={styles.passwordOverlay}>
          <div style={styles.passwordModal}>
            <h3 style={{ marginTop: 0, color: '#2d3748' }}>Changer le mot de passe</h3>
            
            {passwordError && (
              <div style={styles.errorAlert}>
                {passwordError}
              </div>
            )}

            <form onSubmit={handlePasswordSubmit} style={styles.passwordForm}>
              <div style={styles.passwordFormGroup}>
                <label style={styles.passwordLabel}>Mot de passe actuel</label>
                <input
                  type="password"
                  name="currentPassword"
                  value={passwordData.currentPassword}
                  onChange={handlePasswordChange}
                  style={styles.passwordInput}
                  required
                  autoComplete="current-password"
                />
              </div>

              <div style={styles.passwordFormGroup}>
                <label style={styles.passwordLabel}>Nouveau mot de passe</label>
                <input
                  type="password"
                  name="newPassword"
                  value={passwordData.newPassword}
                  onChange={handlePasswordChange}
                  style={{
                    ...styles.passwordInput,
                    ...(passwordData.newPassword && styles[`password${passwordStrength.strength.charAt(0).toUpperCase() + passwordStrength.strength.slice(1)}`])
                  }}
                  required
                  autoComplete="new-password"
                  minLength="6"
                />
                {passwordData.newPassword && (
                  <div style={{
                    ...styles.passwordStrength,
                    ...styles[`password${passwordStrength.strength.charAt(0).toUpperCase() + passwordStrength.strength.slice(1)}`]
                  }}>
                    Force: {passwordStrength.text}
                  </div>
                )}
              </div>

              <div style={styles.passwordFormGroup}>
                <label style={styles.passwordLabel}>Confirmer le nouveau mot de passe</label>
                <input
                  type="password"
                  name="confirmPassword"
                  value={passwordData.confirmPassword}
                  onChange={handlePasswordChange}
                  style={{
                    ...styles.passwordInput,
                    ...(passwordData.confirmPassword && passwordData.newPassword !== passwordData.confirmPassword && styles.passwordInputError)
                  }}
                  required
                  autoComplete="new-password"
                />
                {passwordData.confirmPassword && passwordData.newPassword !== passwordData.confirmPassword && (
                  <div style={styles.passwordError}>
                    Les mots de passe ne correspondent pas
                  </div>
                )}
              </div>

              <div style={styles.passwordActions}>
                <button 
                  type="button" 
                  onClick={cancelPasswordChange}
                  style={styles.cancelButton}
                >
                  Annuler
                </button>
                <button 
                  type="submit"
                  style={styles.saveButton}
                  disabled={
                    !passwordData.currentPassword ||
                    !passwordData.newPassword ||
                    !passwordData.confirmPassword ||
                    passwordData.newPassword !== passwordData.confirmPassword ||
                    passwordData.newPassword.length < 6
                  }
                >
                  💾 Changer le mot de passe
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default StudentProfile;
